async function cnMark(L){const u=S.me.uid;for(const[stt,due,on]of L){const k='cn_'+due+'_'+u+'_'+stt,r=on?{cn:1,stt:+stt,due,by:u,at:Date.now()}:{cn:1,stt:+stt,due,by:u,at:Date.now(),undo:1};await S.db.doc('taskdone/'+k).set(r);S.done.set(k,r)}}

