    if(g('[data-cash]')){payCash().then(()=>{last='';paint()}).catch(x=>alert('Lỗi: '+x.message));return}else if(el=g('[data-crec]')){recvCash(el.dataset.crec,false).then(()=>{last='';paint()}).catch(x=>alert('Lỗi: '+x.message));return}else if(el=g('[data-cshort]')){recvCash(el.dataset.cshort,true).then(()=>{last='';paint()}).catch(x=>alert('Lỗi: '+x.message));return}else if(el=g('[data-cnc]')){const[a,b,on]=el.dataset.cnc.split('|');if(on==='1'){const r=cnDone().get(b+'_'+a);if(r&&r.by!==S.me.uid){alert('Khách này do '+nameOf(r.by)+' đánh dấu.');return}}cnMark([[a,b,on==='1'?0:1]]).then(()=>{last='';paint()}).catch(x=>alert('Lỗi: '+x.message));return}else if(g('[data-cnall]')){const Rg=(cnGroups(cnMine(cnWho()),cnDone()).get(S.cnG)||[]).filter(r=>r.x.s!=='done'&&r.x.s!=='ev');if(!confirm('Đánh dấu đã gửi công nợ cho '+Rg.length+' khách?'))return;cnMark(Rg.map(r=>[r.c[0],r.x.due,1])).then(()=>{last='';paint()}).catch(x=>alert('Lỗi: '+x.message));return}
    else if(g('[data-cno]')){S.cnOpen=true;S.cnG=null;window.scrollTo(0,0)}else if(el=g('[data-cnb]')){if(el.dataset.cnb==='g')S.cnG=null;else S.cnOpen=false}else if(el=g('[data-cnt]')){S.cnTab=el.dataset.cnt}else if(el=g('[data-cnl]')){S.cnL=S.cnL===el.dataset.cnl?null:el.dataset.cnl}else if(el=g('[data-cng]')){S.cnG=el.dataset.cng;window.scrollTo(0,0)}
    else if(g('[data-vh="t"]')){S.open=!S.open}else if(el=g('[data-cvt]')){S.cvTab=el.dataset.cvt}else if(el=g('[data-cvp]')){S.cvOpen=S.cvOpen===el.dataset.cvp?null:el.dataset.cvp}
