  const kt=isQL()&&isKT(),adm=kt||/Cài đặt/.test((document.getElementById('tabs')||{}).textContent||''),ql=isQL()&&(S.me.owner||kt)&&adm,at=activeTab(),md=(ql?at.i+'|'+at.t+'|'+!!S.old:'s'+firstTab());if(md!==S.mode){S.mode=md;last='';S.kat=0}
